VALUES
  ('en', 'policy', 'policy.section6.callout', 'No method of transmission over the internet is 100% secure. While we strive to protect your data, we cannot guarantee absolute security.'),
  ('es', 'policy', 'policy.section6.callout', 'Ningún método de transmisión por Internet es 100% seguro. Si bien nos esforzamos por proteger sus datos, no podemos garantizar una seguridad absoluta.'),
  ('de', 'policy', 'policy.section6.callout', 'Keine Übertragungsmethode über das Internet ist 100 % sicher. Obwohl wir uns um den Schutz Ihrer Daten bemühen, können wir keine absolute Sicherheit garantieren.'),
