  ('zh', 'policy', 'policy.section8.item7.text', '如果处理是基于同意的，则可以随时撤回同意。'),
  ('en', 'policy', 'policy.section8.contact.item1', 'To exercise any of these rights, contact us at privacy@reservehub.com. We will respond within 30 days.'),
